describe("PDFPageView", () => {
  let container;
  let pdfPageView;
  let mockViewport;
  let mockPdfPage;

  beforeEach(() => {
    // Setup DOM environment
    container = document.createElement("div");
    document.body.appendChild(container);

    // Mock PDF page and viewport data
    mockPdfPage = {
      view: [0, 0, 100, 200],
      rotate: 0,
    };

    mockViewport = {
      width: 100,
      height: 200,
      rotation: 0,
      scale: 1,
    };

    // Initialize AppOptions if needed
    if (typeof AppOptions.get !== "function") {
      AppOptions.get = jest.fn((key) => {
        if (key === "maxCanvasPixels") return 16777216;
        if (key === "maxCanvasDim") return 32767;
        if (key === "capCanvasAreaFactor") return 2;
        return null;
      });
    }

    // Instantiate PDFPageView
    pdfPageView = new PDFPageView({
      container,
      defaultViewport: mockViewport,
      scale: 1,
    });

    // Manually set internal state often populated during rendering
    // to allow testing cssTransform without full render logic
    pdfPageView.viewport = mockViewport;
    pdfPageView.pdfPage = mockPdfPage;

    // Access private field #originalViewport to set initial state
    // Note: In a real environment, this is set during draw.
    pdfPageView._originalViewport = mockViewport; 

    // Mock canvas
    const canvas = document.createElement("canvas");
    pdfPageView.canvas = canvas;
  });

  afterEach(() => {
    container.remove();
    jest.clearAllMocks();
  });

  describe("cssTransform", () => {
    it("should return early if there is no canvas", () => {
      pdfPageView.canvas = null;
      expect(() => pdfPageView.cssTransform({})).not.toThrow();
      // The function returns undefined, just checking it doesn't crash
      expect(pdfPageView.cssTransform({})).toBeUndefined();
    });

    it("should not apply transform if viewport rotation matches original rotation", () => {
      pdfPageView.viewport = { ...mockViewport, rotation: 0 };
      pdfPageView._originalViewport = { ...mockViewport, rotation: 0 };

      pdfPageView.cssTransform({});

      expect(pdfPageView.canvas.style.transform).toBe("");
    });

    it("should apply rotate transform for 90 degree relative rotation", () => {
      // Original 0, Current 90 => Relative 90
      pdfPageView.viewport = { ...mockViewport, rotation: 90 };
      pdfPageView._originalViewport = { ...mockViewport, rotation: 0 };

      pdfPageView.cssTransform({});

      // 90 or 270 triggers scaling logic: scaleX = height / width, scaleY = width / height
      // width=100, height=200 => scaleX=2, scaleY=0.5
      expect(pdfPageView.canvas.style.transform).toBe("rotate(90deg) scale(2,0.5)");
    });

    it("should apply rotate transform for 180 degree relative rotation", () => {
      // Original 0, Current 180 => Relative 180
      pdfPageView.viewport = { ...mockViewport, rotation: 180 };
      pdfPageView._originalViewport = { ...mockViewport, rotation: 0 };

      pdfPageView.cssTransform({});

      expect(pdfPageView.canvas.style.transform).toBe("rotate(180deg)");
    });

    it("should apply rotate and scale transform for 270 degree relative rotation", () => {
      // Original 90, Current 0 => (360 + 0 - 90) = 270
      pdfPageView.viewport = { ...mockViewport, rotation: 0 };
      pdfPageView._originalViewport = { ...mockViewport, rotation: 90 };

      pdfPageView.cssTransform({});

      // width=100, height=200 => scaleX=2, scaleY=0.5
      expect(pdfPageView.canvas.style.transform).toBe("rotate(270deg) scale(2,0.5)");
    });

    it("should handle rotation wrapping (e.g. negative or >360)", () => {
      // Original 270, Current 90 => (360 + 90 - 270) = 180
      pdfPageView.viewport = { ...mockViewport, rotation: 90 };
      pdfPageView._originalViewport = { ...mockViewport, rotation: 270 };

      pdfPageView.cssTransform({});

      expect(pdfPageView.canvas.style.transform).toBe("rotate(180deg)");
    });

    it("should hide text layer and struct tree layer when hideTextLayer is true", () => {
      const mockTextLayer = { hide: jest.fn() };
      const mockStructTreeLayer = { hide: jest.fn() };

      pdfPageView.textLayer = mockTextLayer;
      pdfPageView.structTreeLayer = mockStructTreeLayer;

      pdfPageView.cssTransform({ hideTextLayer: true });

      expect(mockTextLayer.hide).toHaveBeenCalled();
      expect(mockStructTreeLayer.hide).toHaveBeenCalled();
    });

    it("should not call textLayer.hide if hideTextLayer is false", () => {
      const mockTextLayer = { hide: jest.fn() };
      pdfPageView.textLayer = mockTextLayer;

      pdfPageView.cssTransform({ hideTextLayer: false });

      expect(mockTextLayer.hide).not.toHaveBeenCalled();
    });

    it("should call private render methods for layers if redraw flags are true", () => {
      // Setup mock layers
      pdfPageView.annotationLayer = {};
      pdfPageView.annotationEditorLayer = {};
      pdfPageView.xfaLayer = {};
      pdfPageView.textLayer = {};

      // Spy on private methods (accessing via # syntax is tricky in Jest, 
